mapper.select:
select t.tenant_id, t.tenant_code, t.tenant_name, t.status, r.role_code
from tenant t
inner join tenant_member m on m.tenant_id = t.tenant_id
inner join tenant_role r on r.role_id = m.role_id and r.tenant_id = t.tenant_id
where t.tenant_id = #{tenantId}
  and m.user_id = #{userId}
  and m.member_status = #{memberStatus}
